import{_ as i,o as l,c as e,a0 as t}from"./chunks/framework.CnTYizyl.js";const u=JSON.parse('{"title":"智慧养老管理平台｜大创全栈项目","description":"","frontmatter":{},"headers":[],"relativePath":"posts/first.md","filePath":"posts/first.md"}'),r={name:"posts/first.md"};function o(n,a,s,h,d,c){return l(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="智慧养老管理平台-大创全栈项目" tabindex="-1">智慧养老管理平台｜大创全栈项目 <a class="header-anchor" href="#智慧养老管理平台-大创全栈项目" aria-label="Permalink to &quot;智慧养老管理平台｜大创全栈项目&quot;">​</a></h1><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p>本项目是大创立项的智慧养老管理平台，面向社区养老场景，为老人、家属、管理员提供一体化服务。 系统包含老人基础信息管理、药品图像识别用药提醒、健康数据录入、养老知识库AI问答功能。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><ul><li>后端：Java，SpringBoot，Spring AI</li><li>前端：Vue3 + TypeScript</li><li>AI模块：RAG本地知识库、药品图像识别</li></ul><h2 id="个人职责" tabindex="-1">个人职责 <a class="header-anchor" href="#个人职责" aria-label="Permalink to &quot;个人职责&quot;">​</a></h2><ol><li>后端业务接口开发，完成老人信息、健康档案CRUD接口</li><li>基于SpringAI接入大模型，搭建养老领域RAG知识库，实现智能问答</li><li>对接图像识别能力，实现药品图片识别，生成用药提醒</li><li>参与需求分析、数据库表设计，撰写项目申报材料与文档</li></ol><h2 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h2><p>前端Vue3页面 → 请求SpringBoot后端接口 → SpringAI大模型服务 + 图像识别模块 → MySQL存储老人、健康、药品数据</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ol><li>用户登录权限区分：管理员/家属角色</li><li>老人健康档案维护，记录血压、心率等健康指标</li><li>药品拍照识别，自动解析药品信息、用药周期并提醒</li><li>AI养老问答：老人及家属可以提问养老、护理相关问题</li></ol><h2 id="项目难点与解决方案" tabindex="-1">项目难点与解决方案 <a class="header-anchor" href="#项目难点与解决方案" aria-label="Permalink to &quot;项目难点与解决方案&quot;">​</a></h2><ol><li><p>问题：通用大模型回答内容宽泛，容易输出无关信息 解决：使用RAG，导入养老相关文档构建私有知识库，限制回答范围。</p></li><li><p>问题：药品图片识别准确率不足 解决：筛选药品关键特征，预处理图片，过滤无效图片干扰。</p></li></ol><h2 id="项目成果" tabindex="-1">项目成果 <a class="header-anchor" href="#项目成果" aria-label="Permalink to &quot;项目成果&quot;">​</a></h2><ol><li>完成前后端完整demo，实现全部预设功能，用于大创申报</li><li>项目申报省级大创，持续迭代优化</li></ol>',15)])])}const _=i(r,[["render",o]]);export{u as __pageData,_ as default};
